func loadReportPromptGolden(t *testing.T) reportPromptGolden {
	t.Helper()
	var golden reportPromptGolden
	if err := json.Unmarshal([]byte(reportPromptGoldenJSON), &golden); err != nil {
		t.Fatal(err)
	}
	return golden
}

func sha256Text(value string) string {
	sum := sha256.Sum256([]byte(value))
	return hex.EncodeToString(sum[:])
}

func TestReportPromptSelectionMatchesPreMoveGolden(t *testing.T) {
	golden := loadReportPromptGolden(t)
	if len(golden.Selections) != 378 {
		t.Fatalf("golden selection coverage changed: got %d", len(golden.Selections))
	}
	for _, want := range golden.Selections {
		want := want
		t.Run(want.Mode+"/"+strings.ReplaceAll(want.Input, "/", "_"), func(t *testing.T) {
			profile, gotSHA, err := SelectReportGenerationGuidanceForMode(want.Mode, want.Input)
			if profile != want.Profile || gotSHA != want.SHA {
				t.Fatalf("got profile=%q sha=%q, want profile=%q sha=%q", profile, gotSHA, want.Profile, want.SHA)
			}
			gotErr := ""
			gotInvalid := false
			if err != nil {
				gotErr = err.Error()
				gotInvalid = errors.Is(err, producterror.ErrInvalidInput)
			}
			if gotErr != want.Err || gotInvalid != want.Invalid {
				t.Fatalf("got err=%q invalid=%t, want err=%q invalid=%t", gotErr, gotInvalid, want.Err, want.Invalid)
			}
		})
	}
}

func TestReportPromptHelpersMatchPreMoveGolden(t *testing.T) {
	golden := loadReportPromptGolden(t)
	if len(golden.Helpers) != 114 {
		t.Fatalf("golden helper coverage changed: got %d", len(golden.Helpers))
	}
	for _, want := range golden.Helpers {
		want := want
		t.Run(want.Name+"/"+strings.ReplaceAll(want.Input, "/", "_"), func(t *testing.T) {
			switch want.Name {
			case "planning":
				assertGoldenSHA(t, want, ReportGenerationPlanningGuidance(want.Input))
			case "regular":
				assertGoldenSHA(t, want, ReportGenerationGuidance(want.Input))
			case "longform":
				assertGoldenSHA(t, want, LongFormReportGenerationGuidance(want.Input))
			case "longform_experimental_planning":
				assertGoldenSHA(t, want, LongFormExperimentalPlanningGuidance(want.Input))
			case "section_direct":
				assertGoldenSHA(t, want, SectionDirectWritingGuidance(want.Input))
			case "part_connective":
				assertGoldenSHA(t, want, PartConnectiveEconomyGuidance(want.Input))
			case "subject_planning":
				assertGoldenSHA(t, want, SubjectDirectSynthesisPlanningGuidance(want.Input))
			case "subject_section":
				assertGoldenSHA(t, want, SubjectDirectSynthesisSectionGuidance(want.Input))
			case "visual_planning":
				assertGoldenSHA(t, want, VisualAidPlanningGuidance(want.Input))
			case "mermaid":
				if got := ReportMermaidValidationRule(); got != want.Text {
					t.Fatalf("Mermaid rule changed:\ngot:  %q\nwant: %q", got, want.Text)
				}
				assertGoldenSHA(t, want, ReportMermaidValidationRule())
			case "post_humanize":
				if got := NormalizePostReportHumanize(want.Input); got != want.String {
					t.Fatalf("got %q, want %q", got, want.String)
				}
			case "writing_contract":
				if got := RequireReportWritingContract(want.Input); got != want.Bool {
					t.Fatalf("got %t, want %t", got, want.Bool)
				}
			case "composition":
				if got := LongFormCompositionStrategy(want.Input); got != want.String {
					t.Fatalf("got %q, want %q", got, want.String)
				}
			default:
				t.Fatalf("unhandled golden helper %q", want.Name)
			}
		})
	}
}

func assertGoldenSHA(t *testing.T, want goldenHelper, value string) {
	t.Helper()
	if got := sha256Text(value); got != want.SHA {
		t.Fatalf("sha=%q want %q for output:\n%s", got, want.SHA, value)
	}
}
